def _expression_to_sql(expression, node, context):
    """Recursively transform a Filter block predicate to its SQLAlchemy expression representation.

    Args:
        expression: expression, the compiler expression to transform.
        node: SqlNode, the SqlNode the expression applies to.
        context: CompilationContext, global compilation state and metadata.

    Returns:
        Expression, SQLAlchemy Expression equivalent to the passed compiler expression.
    """
    if isinstance(expression, Literal):
        return expression.value

    if isinstance(expression, Field):
        return node.get_field(expression.name)

    if isinstance(expression, Operator):
        if expression.operator == '=':
            return _expression_to_sql(expression.left, node, context) == _expression_to_sql(expression.right, node, context)
        elif expression.operator == '!=':
            return _expression_to_sql(expression.left, node, context) != _expression_to_sql(expression.right, node, context)
        elif expression.operator == '<':
            return _expression_to_sql(expression.left, node, context) < _expression_to_sql(expression.right, node, context)
        elif expression.operator == '<=':
            return _expression_to_sql(expression.left, node, context) <= _expression_to_sql(expression.right, node, context)
        elif expression.operator == '>':
            return _expression_to_sql(expression.left, node, context) > _expression_to_sql(expression.right, node, context)
        elif expression.operator == '>=':
            return _expression_to_sql(expression.left, node, context) >= _expression_to_sql(expression.right, node, context)
        elif expression.operator == 'in':
            return _expression_to_sql(expression.left, node, context).in_(_expression_to_sql(expression.right, node, context))
        elif expression.operator == 'not in':
            return _expression_to_sql(expression.left, node, context).notin(_expression_to_sql(expression.right, node, context))
        elif expression.operator == 'is':
            return _expression_to_sql(expression.left, node, context) == _expression_to_sql(expression.right, node, context)
        elif expression.operator == 'is not':
            return _expression_to_sql(expression.left, node, context) != _expression_to_sql(expression.right, node, context)
        elif expression.operator == 'not':
            return not _expression_

